import openpyxl, os
wb=openpyxl.load_workbook(os.environ['IN_XLSX'])
for name in ['cdnr','b2b, sez, de','Expected']:
    ws=wb[name]
    print('===',name, ws.max_row, ws.max_column)
    last=0
    for r in range(1,ws.max_row+1):
        if ws.cell(r,1).value not in (None,''):
            last=r
    print('last A row', last)
    for r in range(4,11):
        vals=[ws.cell(r,c).value for c in range(1,23)]
        print(r, vals)
